import { expect, test } from '@playwright/test';
import { arrange, ID, VendorPay } from '../support/vendorpay';

// Generated by the agent core for CMP-002 (myClara read the rule, myTessa designed the checks, myGenie wrote them).
// V5 Audit trail: a rejected bank change is justified, and the justification is kept.

test('V5/bank-change-rejection-needs-reason', async ({ request }, info) => {
  const vp = new VendorPay(request);
  const change = await arrange('a requested bank change', async () => vp.requestBankChange(ID.procurement, (await vp.activeSupplier('reject-reason')).id));
  const res = await vp.call(ID.approverA, 'POST', `/api/bank-change-requests/${change.id}/reject`, { note: '' });
  const after = (await vp.json(ID.auditor, 'GET', `/api/bank-change-requests/${change.id}`, undefined, 200)).request;
  await info.attach('observation', { contentType: 'application/json', body: JSON.stringify({ request: change.id, rejectStatus: res.status(), statusAfter: after.status }) });
  expect(res.status(), 'rejecting without a reason is refused').toBe(422);
  expect(after.status, 'the request stays open').toBe('requested');
});

test('V5/bank-change-rejection-reason-recorded', async ({ request }, info) => {
  const vp = new VendorPay(request);
  const reason = `PRCheck.live verification: account holder name does not match ${Date.now().toString(36)}`;
  const { supplier, change } = await arrange('a requested bank change', async () => {
    const supplier = await vp.activeSupplier('reject-recorded');
    return { supplier, change: await vp.requestBankChange(ID.procurement, supplier.id) };
  });
  await vp.json(ID.approverA, 'POST', `/api/bank-change-requests/${change.id}/reject`, { note: reason }, 200);
  const record = (await vp.json(ID.auditor, 'GET', `/api/bank-change-requests/${change.id}`, undefined, 200)).request;
  const event = (await vp.auditFor(supplier.id)).find((e) => e.type === 'BANK_CHANGE_REJECTED');
  await info.attach('observation', { contentType: 'application/json', body: JSON.stringify({ request: change.id, decisionNote: record.decisionNote, auditNote: event?.details?.note ?? null, actor: event?.actor ?? null }) });
  expect(record.decisionNote, 'the reason is kept on the request').toBe(reason);
  expect(event?.details?.note, 'the reason is in the audit event').toBe(reason);
  expect(event?.actor).toBe(ID.approverA);
});
